-- v5.0.0 source IP policy. Generated by tools/v500_generate_network_access.py.

-- Default disabled; revision/rules and their audit are committed atomically by platform services.

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_IP_ACCESS_REVISIONS'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_IP_ACCESS_REVISIONS (REVISION INTEGER PRIMARY KEY CHECK(REVISION>0), ENABLED VARCHAR(1) NOT NULL CHECK(ENABLED IN (''Y'',''N'')), LIST_MODE VARCHAR(16) NOT NULL CHECK(LIST_MODE IN (''ALLOWLIST'',''DENYLIST'')), UPDATED_BY VARCHAR(128) NOT NULL, REASON VARCHAR(2000) NOT NULL, CREATED_AT TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL)'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_IP_ACCESS_STATE'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_IP_ACCESS_STATE (POLICY_KEY VARCHAR(16) PRIMARY KEY CHECK(POLICY_KEY=''GLOBAL''), REVISION INTEGER NOT NULL REFERENCES CX_IP_ACCESS_REVISIONS(REVISION))'; END IF; END;
/

DECLARE n NUMBER; BEGIN SELECT COUNT(*) INTO n FROM USER_TABLES WHERE TABLE_NAME='CX_IP_ACCESS_RULES'; IF n=0 THEN EXECUTE IMMEDIATE 'CREATE TABLE CX_IP_ACCESS_RULES (REVISION INTEGER NOT NULL REFERENCES CX_IP_ACCESS_REVISIONS(REVISION), RULE_NO INTEGER NOT NULL CHECK(RULE_NO>=1 AND RULE_NO<=512), NETWORK_CIDR VARCHAR(64) NOT NULL, IP_VERSION INTEGER NOT NULL CHECK(IP_VERSION IN (4,6)), PRIMARY KEY(REVISION,RULE_NO), UNIQUE(REVISION,NETWORK_CIDR))'; END IF; END;
/

INSERT INTO CX_IP_ACCESS_REVISIONS(REVISION,ENABLED,LIST_MODE,UPDATED_BY,REASON) SELECT 1,'N','DENYLIST','SYSTEM_BOOTSTRAP','Initial disabled source IP policy' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM CX_IP_ACCESS_REVISIONS WHERE REVISION=1);

INSERT INTO CX_IP_ACCESS_STATE(POLICY_KEY,REVISION) SELECT 'GLOBAL',1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM CX_IP_ACCESS_STATE WHERE POLICY_KEY='GLOBAL');

CREATE OR REPLACE TRIGGER CX102_REVISIONS BEFORE DELETE OR UPDATE OF REVISION,ENABLED,LIST_MODE,UPDATED_BY,REASON,CREATED_AT ON CX_IP_ACCESS_REVISIONS DECLARE ip_policy_immutable EXCEPTION; BEGIN RAISE ip_policy_immutable; END;
/

BEGIN FOR g IN (SELECT GRANTEE,PRIVILEGE FROM ALL_TAB_PRIVS WHERE OWNER=USER AND TABLE_NAME='CX_IP_ACCESS_REVISIONS') LOOP EXECUTE IMMEDIATE 'REVOKE '||g.PRIVILEGE||' ON CX_IP_ACCESS_REVISIONS FROM "'||REPLACE(g.GRANTEE,'"','""')||'"'; END LOOP; END;
/

CREATE OR REPLACE TRIGGER CX102_STATE BEFORE DELETE OR UPDATE OF POLICY_KEY ON CX_IP_ACCESS_STATE DECLARE ip_policy_immutable EXCEPTION; BEGIN RAISE ip_policy_immutable; END;
/

BEGIN FOR g IN (SELECT GRANTEE,PRIVILEGE FROM ALL_TAB_PRIVS WHERE OWNER=USER AND TABLE_NAME='CX_IP_ACCESS_STATE') LOOP EXECUTE IMMEDIATE 'REVOKE '||g.PRIVILEGE||' ON CX_IP_ACCESS_STATE FROM "'||REPLACE(g.GRANTEE,'"','""')||'"'; END LOOP; END;
/

CREATE OR REPLACE TRIGGER CX102_RULES BEFORE DELETE OR UPDATE OF REVISION,RULE_NO,NETWORK_CIDR,IP_VERSION ON CX_IP_ACCESS_RULES DECLARE ip_policy_immutable EXCEPTION; BEGIN RAISE ip_policy_immutable; END;
/

BEGIN FOR g IN (SELECT GRANTEE,PRIVILEGE FROM ALL_TAB_PRIVS WHERE OWNER=USER AND TABLE_NAME='CX_IP_ACCESS_RULES') LOOP EXECUTE IMMEDIATE 'REVOKE '||g.PRIVILEGE||' ON CX_IP_ACCESS_RULES FROM "'||REPLACE(g.GRANTEE,'"','""')||'"'; END LOOP; END;
/
